{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "cardiac_safe_12wk_general_fitness",
    "name": "12-week General Fitness (Post-MI, Moderate Intensity)",
    "description": "12-week conservative gym program for a 58-year-old male cleared for moderate-intensity exercise post-MI. Targets general fitness, functional strength, mobility and aerobic conditioning while keeping intensity below ~70% age-predicted HRmax (~115 bpm). Avoids Valsalva and maximal lifts.",
    "type": "hybrid",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "created_by": "trainer",
      "difficulty": "adaptive",
      "language": "en",
      "estimated_duration_days": 84,
      "tags": [
        "post-mi",
        "cardiac_rehab",
        "moderate_intensity",
        "general_fitness"
      ]
    },
    "goals": [
      {
        "id": "primary_general_fitness",
        "type": "primary",
        "category": "general_fitness",
        "name": "Improve general fitness and functional strength safely",
        "description": "Progress aerobic endurance, mobility and strength with conservative intensities appropriate for cardiac rehab clearance.",
        "target": {
          "metric": "session_rpe_avg",
          "target_value": 5,
          "unit": "rpe_borg_10",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "milestone_4w",
            "name": "4-week consistency",
            "target_value": 4,
            "reward_points": 50
          },
          {
            "id": "milestone_8w",
            "name": "8-week progress",
            "target_value": 8,
            "reward_points": 100
          },
          {
            "id": "milestone_12w",
            "name": "12-week completion",
            "target_value": 12,
            "reward_points": 200
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 120,
      "fitness_level": [
        "beginner",
        "intermediate"
      ],
      "equipment": [
        {
          "id": "gym_basics",
          "name": "Full gym access (machines, dumbbells, cables, treadmill/bike)",
          "required": true,
          "alternatives": [
            "recumbent_bike",
            "elliptical"
          ]
        }
      ],
      "contraindications": [
        {
          "condition": "acsm:cardiac_rehab_phase_2",
          "severity": "high",
          "action": "modify",
          "affected_activities": []
        },
        {
          "condition": "post_mi_no_valsalva",
          "severity": "high",
          "action": "modify",
          "affected_activities": []
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 5,
        "min_minutes_per_day": 20,
        "max_minutes_per_day": 70
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "user_age",
          "type": "number",
          "source": "user.age",
          "label": "Age"
        },
        {
          "id": "user_resting_hr",
          "type": "number",
          "source": "user.resting_hr_bpm",
          "label": "Resting heart rate (bpm)"
        },
        {
          "id": "user_hr_clearance_max",
          "type": "number",
          "source": "user.hr_max_bpm",
          "label": "Cleared heart rate max (bpm)"
        },
        {
          "id": "user_equipment",
          "type": "array",
          "source": "user.equipment",
          "label": "Available equipment"
        }
      ],
      "rules": [
        {
          "id": "use_cleared_hr",
          "condition": {
            "field": "user_hr_clearance_max",
            "op": "gt",
            "value": 0
          },
          "actions": [
            {
              "type": "set",
              "scope": "plan.metadata",
              "hr_limit_from_input": "user_hr_clearance_max"
            }
          ]
        }
      ]
    },
